package com.example.helpdesk.service;
import com.example.helpdesk.dto.TicketEditForm; import com.example.helpdesk.exception.ResourceNotFoundException; import com.example.helpdesk.model.*; import com.example.helpdesk.repo.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TicketService {private final TicketRepository tickets;private final UserRepository users;private final TicketHistoryRepository history;public TicketService(TicketRepository t,UserRepository u,TicketHistoryRepository h){tickets=t;users=u;history=h;}public List<Ticket> visible(User u,String q,Priority priority){List<Ticket> result;if(u.getRole()==Role.EMPLOYEE)result=tickets.findByReporterOrderByUpdatedAtDesc(u);else result=q==null||q.isBlank()?tickets.findAll():tickets.search(q);if(priority!=null)result=result.stream().filter(t->t.getPriority()==priority).toList();return result;}@Transactional public Ticket create(Ticket t,String name){User u=users.findByUsername(name).orElseThrow();if(t.getTitle()==null||t.getTitle().isBlank())throw new IllegalArgumentException("Title is required");t.setReporter(u);t.setStatus(TicketStatus.OPEN);if(t.getPriority()==null)t.setPriority(Priority.MEDIUM);Ticket saved=tickets.save(t);history.save(new TicketHistory(saved,u,"Created","Ticket submitted"));return saved;}public Ticket get(Long id){return tickets.findById(id).orElseThrow(()->new ResourceNotFoundException("Ticket not found: "+id));}public List<TicketHistory> history(Long id){return history.findByTicketOrderByCreatedAtDesc(get(id));}
 @Transactional public Ticket updateTicket(Long id,TicketEditForm form,String name){Ticket t=get(id);User actor=users.findByUsername(name).orElseThrow();if(form.getTitle()==null||form.getTitle().isBlank())throw new IllegalArgumentException("Title is required");if(form.getDescription()==null||form.getDescription().isBlank())throw new IllegalArgumentException("Description is required");if(form.getCategory()==null)throw new IllegalArgumentException("Category is required");if(form.getPriority()==null)throw new IllegalArgumentException("Priority is required");boolean tech=actor.getRole()==Role.TECHNICIAN;if(!tech&&(!actor.equals(t.getReporter())||t.getStatus()!=TicketStatus.OPEN))throw new AccessDeniedException("You cannot edit this ticket");saveChange(t,actor,"title",t.getTitle(),form.getTitle());saveChange(t,actor,"description",t.getDescription(),form.getDescription());saveChange(t,actor,"category",String.valueOf(t.getCategory()),String.valueOf(form.getCategory()));saveChange(t,actor,"priority",String.valueOf(t.getPriority()),String.valueOf(form.getPriority()));t.setTitle(form.getTitle().trim());t.setDescription(form.getDescription());t.setCategory(form.getCategory());t.setPriority(form.getPriority());if(tech){if(form.getStatus()!=null&&form.getStatus()!=t.getStatus()){if(form.getStatus()==TicketStatus.RESOLVED&&(form.getResolutionNotes()==null||form.getResolutionNotes().isBlank()))throw new IllegalArgumentException("Resolution notes are required");history.save(new TicketHistory(t,actor,"STATUS_CHANGED","Status updated","status",String.valueOf(t.getStatus()),String.valueOf(form.getStatus())));t.setStatus(form.getStatus());}if(form.getTechnicianId()!=null){User assignee=users.findById(form.getTechnicianId()).orElseThrow(()->new ResourceNotFoundException("Technician not found"));t.setTechnician(assignee);history.save(new TicketHistory(t,actor,"ASSIGNED","Ticket assigned","technician",null,assignee.getUsername()));}if(form.getResolutionNotes()!=null&&!form.getResolutionNotes().equals(t.getResolutionNotes())){history.save(new TicketHistory(t,actor,"RESOLUTION_UPDATED","Resolution notes updated","resolutionNotes",t.getResolutionNotes(),form.getResolutionNotes()));t.setResolutionNotes(form.getResolutionNotes());}}t.setUpdatedAt(java.time.LocalDateTime.now());return tickets.save(t);}
 private void saveChange(Ticket t,User actor,String field,String oldValue,String newValue){if(!Objects.equals(oldValue,newValue))history.save(new TicketHistory(t,actor,"FIELD_CHANGED","Ticket field updated",field,oldValue,newValue));}
 @Transactional public Ticket updateFields(Long id,String title,String description,Category category,Priority priority,String name){TicketEditForm f=new TicketEditForm();f.setTitle(title);f.setDescription(description);f.setCategory(category);f.setPriority(priority);return updateTicket(id,f,name);}@Transactional public void updateStatus(Long id,TicketStatus status,String notes,String name){Ticket t=get(id);User actor=users.findByUsername(name).orElseThrow();if(status==TicketStatus.RESOLVED&&(notes==null||notes.isBlank()))throw new IllegalArgumentException("Resolution notes are required");t.setStatus(status);t.setResolutionNotes(notes);tickets.save(t);history.save(new TicketHistory(t,actor,"STATUS_CHANGED","New status: "+status));}public long count(TicketStatus s){return tickets.countByStatus(s);}}
